bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
path="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
test -n "$path" && test -f "$path" && test ! -L "$path" || exit 61
docker run --rm --network none --pull never \
 --mount "type=bind,source=$path,target=/run/secrets/videobot_db_password,readonly" \
 --entrypoint node create-videobot:local-poll -e '
const {statSync}=require("node:fs");
const s=statSync("/run/secrets/videobot_db_password");
if(!s.isFile())process.exit(80);
if((s.mode & 0o077)!==0)process.exit(81);
if(s.size<12)process.exit(82);
if(s.size>4096)process.exit(83);
if(s.uid!==process.getuid())process.exit(84);
process.exit(0);
'
